-- Consolida o catálogo servido no RDS e substitui duas opções ativas.
-- Históricos, preços e contribuições das origens permanecem intactos.
BEGIN;
SET LOCAL lock_timeout = '10s';
ALTER TABLE food_catalog ADD COLUMN IF NOT EXISTS remote_id TEXT;
ALTER TABLE food_catalog ADD COLUMN IF NOT EXISTS details JSONB;
ALTER TABLE food_catalog ADD COLUMN IF NOT EXISTS active BOOLEAN NOT NULL DEFAULT TRUE;
CREATE UNIQUE INDEX IF NOT EXISTS food_catalog_remote_id_idx ON food_catalog(remote_id);
ALTER TABLE grocery_ingredients ADD COLUMN IF NOT EXISTS details JSONB;
ALTER TABLE grocery_ingredients ADD COLUMN IF NOT EXISTS active BOOLEAN NOT NULL DEFAULT TRUE;
CREATE TABLE IF NOT EXISTS nutrition_catalog_settings (
 id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL CHECK(revision>0), policy JSONB NOT NULL
);
-- Abortamos em vez de sobrescrever uma tabela nutricional já ocupada.
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM food_catalog WHERE remote_id IS NULL) THEN
  RAISE EXCEPTION 'Catálogo nutricional legado ocupado; revisar migração antes de aplicar';
 END IF;
END $$;
