INSERT INTO grocery_ingredients(slug,name,unit,details,active)
SELECT i->>'slug',i->>'name',i->>'unit',i,(i->>'slug') NOT IN ('arroz-negro-integral','soja-verde-em-graos-edamame')
FROM seed ON CONFLICT(slug) DO UPDATE SET details=EXCLUDED.details,active=EXCLUDED.active;
UPDATE food_catalog SET active=FALSE WHERE remote_id IN ('food_130','food_135');
INSERT INTO nutrition_catalog_settings(id,revision,policy) VALUES(1,2,'{"required_groups":[["catalog_arroz_branco_tipo_1","food_132"],["food_121","food_122"]]}'::jsonb) ON CONFLICT(id) DO NOTHING;
DO $$ BEGIN
 IF (SELECT count(*) FROM food_catalog WHERE active) <> 220 THEN
  RAISE EXCEPTION 'Quantidade ativa inesperada no catálogo nutricional';
 END IF;
 IF EXISTS(SELECT 1 FROM food_catalog f, jsonb_array_elements_text(f.details->'shoppingComponents') s
  WHERE f.active AND NOT EXISTS(SELECT 1 FROM grocery_ingredients i WHERE i.slug=s AND i.active)) THEN
  RAISE EXCEPTION 'Vínculo de compra ausente ou inativo';
 END IF;
END $$;
COMMIT;
